edits.after:
if (*cow_len == 0) {
	/*
	 * We should find a refcounted record in the
	 * first pass.
	 */
	if (le32_to_cpu(rec->e_cpos) > cpos) {
		return ocfs2_error(inode->i_sb,
				   "Inode %lu: cpos %u is a hole but refcount cow is called\n",
				   inode->i_ino, cpos);
	}
	if (!(rec->e_flags & OCFS2_EXT_REFCOUNTED)) {
		return ocfs2_error(inode->i_sb,
				   "Inode %lu: extent at cpos %u is not refcounted but refcount cow is called\n",
				   inode->i_ino, cpos);
	}
	*cow_start = le32_to_cpu(rec->e_cpos);
}

